1| """Will of the Prophets game board."""
2| 
3| from functools import lru_cache
4| 
5| from django.core import signals
6| from django.template.loader import render_to_string
7| from django.utils import timezone
8| 
9| from will_of_the_prophets import models
10| 
11| 
12| @lru_cache(maxsize=1)
13| def get_buttholes():
14|     """Get butthole starts and ends."""
15|     return dict(models.Butthole.objects.values_list("start_square", "end_square"))
16| 
17| 
18| @lru_cache(maxsize=1)
19| def get_special_squares():
20|     """Get special square types keyed on squares they appear in."""
21|     squares = dict()
22|     for square in models.SpecialSquare.objects.select_related().all():
23|         squares[square.square] = square.type
24|     return squares
25| 
26| 
27| def clear_caches(**kwargs):  # pylint: disable=unused-argument
28|     """Clear cached results of buttholes and special squares."""
29|     get_buttholes.cache_clear()
30|     get_special_squares.cache_clear()
31| 
32| 
33| signals.request_started.connect(clear_caches)
34| 
35| 
36| def calculate_position(*rolls):
37|     """Calculate the current position."""
38|     buttholes = get_buttholes()
39|     special_squares = get_special_squares()
40|     position = 1
41|     for roll in rolls:
42|         position += roll
43|         if position in special_squares:
44|             position = position + special_squares[position].auto_move
45| 
46|         if position in buttholes:
47|             position = buttholes[position]
48| 
49|     return (position - 1) % 100 + 1
50| 
51| 
52| class Square:
53|     """A square in the board."""
54| 
55|     def __init__(self, number, row_reversed=False, is_current_position=False):
56|         self.number = number
57|         self.row_reversed = row_reversed
58|         self.is_current_position = is_current_position
59| 
60|     @property
61|     def special(self):
62|         return get_special_squares().get(self.number)
63| 
64|     @property
65|     def butthole_start(self):
66|         return self.number in get_buttholes()
67| 
68|     @property
69|     def butthole_ends(self):
70|         """Get the starting squares of any buttholes which end here."""
71|         butthole_ends = []
72|         for start, end in get_buttholes().items():
73|             if end == self.number:
74|                 butthole_ends.append(start)
75| 
76|         return butthole_ends
77| 
78|     @property
79|     def row_break_after(self):
80|         return str(self.number)[-1] == "1"
81| 
82| 
83| def square_numbers():
84|     """
85|     Square numbers in order, and whether the row is reversed.
86| 
87|     Starting from the bottom of the board, the first row of squares runs
88|     left-to-right, the second row runs right-to-left (that is, reversed),
89|     the third row runs left-to-right, and so on.
90|     """
91|     for row_number in reversed(range(0, 10)):
92|         first_square = row_number * 10 + 1
93|         numbers = range(first_square, first_square + 10)
94|         row_reversed = False
95|         if row_number % 2:
96|             numbers = reversed(numbers)
97|             row_reversed = True
98| 
99|         for number in numbers:
100|             yield (number, row_reversed)
101| 
102| 
103| class Board:
104|     """The Will of the Prophets board at any given time."""
105| 
106|     def __init__(self, now=None):
107|         if not now:
108|             now = timezone.now()
109| 
110|         self.now = now
111| 
112|     @property
113|     def squares(self):
114|         """The 100 squares which make up the board."""
115|         current_position = self.get_current_position()
116|         for square_number, row_reversed in square_numbers():
117|             is_current_position = square_number == current_position
118|             yield Square(
119|                 number=square_number,
120|                 row_reversed=row_reversed,
121|                 is_current_position=is_current_position,
122|             )
123| 
124|     @property
125|     def rolls(self):
126|         return (
127|             models.Roll.objects.filter(embargo__lte=self.now)
128|             .order_by("embargo")
129|             .values_list("number", flat=True)
130|         )
131| 
132|     def get_current_position(self):
133|         """Get the current position."""
134|         return calculate_position(*self.rolls)
135| 
136|     def __str__(self):
137|         return render_to_string(
138|             "will_of_the_prophets/board/board.html", {"squares": self.squares}
139|         )

